const SURFACE_CLOSE=`\x1B[49m`,ERROR_ACCENT={r:230,g:105,b:123},WHITE={r:255,g:255,b:255},BLACK={r:0,g:0,b:0};function deriveTraceViewerSurfaces(e){let r=relativeLuminance(e)<.5?WHITE:BLACK,i=foregroundOpen(r),a=foregroundOpen(mix(e,r,.55));return{header:backgroundOpen(mix(e,r,.086)),body:backgroundOpen(mix(e,r,.141)),errorHeader:backgroundOpen(mix(e,ERROR_ACCENT,.3)),errorBody:backgroundOpen(mix(e,ERROR_ACCENT,.25)),primaryText:e=>`${i}${e}\x1b[39m`,mutedText:e=>`${a}${e}\x1b[39m`}}function backgroundOpen(e){return`\x1b[48;2;${e.r};${e.g};${e.b}m`}function foregroundOpen(e){return`\x1b[38;2;${e.r};${e.g};${e.b}m`}function mix(e,t,n){let blend=(e,t)=>Math.round(e+(t-e)*n);return{r:blend(e.r,t.r),g:blend(e.g,t.g),b:blend(e.b,t.b)}}function relativeLuminance(e){return(.2126*e.r+.7152*e.g+.0722*e.b)/255}export{SURFACE_CLOSE,deriveTraceViewerSurfaces};